p=Path('gps/gps-panel.css'); s=p.read_text(); s += r'''
/* GPS report cleanup v2 */
.patx-gps-head-actions .patx-gps-orientation{margin:0;max-width:360px;padding:9px 10px;justify-content:flex-end}.patx-gps-head-actions .patx-gps-orientation>span{display:none}.patx-gps-head-actions .patx-gps-orientation small{flex-basis:100%;text-align:right}.patx-gps-highlights{display:grid;gap:0;margin:8px 0 14px;padding:14px 18px;border-radius:16px;background:#0b120e;border:1px solid rgba(255,255,255,.1)}.patx-gps-highlight-row{display:grid;grid-template-columns:58px 1fr;gap:12px;padding:10px 0;border-top:1px solid rgba(255,255,255,.07)}.patx-gps-highlight-row:first-of-type{border-top:0}.patx-gps-highlight-row>strong{font-size:20px;color:#f2f4f3}.patx-gps-highlight-row b,.patx-gps-highlight-row span{display:block}.patx-gps-highlight-row b{font-size:13px}.patx-gps-highlight-row span{font-size:10px;color:#89958e;margin-top:2px}.patx-gps-chart-tooltip{position:absolute;top:14px;transform:translateX(-50%);pointer-events:none;z-index:6}.patx-gps-chart-tooltip[hidden]{display:none}.patx-gps-chart-tooltip:before{content:"";position:absolute;left:50%;top:28px;height:155px;border-left:1px solid rgba(255,255,255,.28)}.patx-gps-chart-tooltip b{display:block;white-space:nowrap;padding:5px 7px;border-radius:7px;background:#f3f5f4;color:#09100c;font-size:10px;box-shadow:0 5px 16px rgba(0,0,0,.35)}.patx-match-gps-table-wrap{margin:14px 0;padding:14px;border-radius:14px;background:rgba(11,18,14,.72);border:1px solid rgba(255,255,255,.12)}.patx-match-gps-table-wrap h4{margin:0 0 9px;font-size:15px}.patx-match-gps-table{display:grid;gap:6px}.patx-match-gps-row{display:grid;grid-template-columns:1fr auto auto;gap:10px;align-items:center;padding:10px 11px;border-radius:10px;background:rgba(255,255,255,.055)}.patx-match-gps-player strong,.patx-match-gps-player small{display:block}.patx-match-gps-player strong{font-size:12px}.patx-match-gps-player small{color:#99a49d;font-size:9px;margin-top:2px}.patx-match-watch{font-size:20px}.patx-match-gps-row button{border:1px solid rgba(255,255,255,.15);background:#18211c;color:#f2f4f3;border-radius:8px;padding:8px 10px;font-size:10px;font-weight:850;cursor:pointer}.patx-gps-icon-btn>span{font-size:14px;line-height:1}.patx-gps-details[open]>summary i{transform:rotate(45deg)}
@media(max-width:700px){.patx-gps-head-actions{width:100%}.patx-gps-head-actions .patx-gps-orientation{max-width:none;width:100%;align-items:flex-start}.patx-gps-head-actions .patx-gps-orientation small{text-align:left}.patx-match-gps-row{grid-template-columns:1fr auto}.patx-match-gps-row button{grid-column:1/-1;width:100%}}
'''; p.write_text(s)
